-- evt:black_barrel
RegisterEvent(4, "Black barrel", function(continueStep)
    if continueStep == 2 then
        evt.ForPlayer(Players.Current)
        for _, stat in ipairs({BaseMight, BaseIntellect, BasePersonality, BaseEndurance, BaseSpeed, BaseAccuracy, BaseLuck}) do
            AddValue(stat, 1)
        end
        AddValue(Age, 1)
        SetPlayerBit(PlayerBit(11317))
        evt.SimpleMessage("Your statistics have improved, but you have suffered a little magical aging.")
        return
    end
    if continueStep ~= nil then
        return
    end
    if not (not (IsPlayerBitSet(PlayerBit(11317)))) then
        evt.StatusText("The black sludge has done all it will do to you.", 5)
        return
    end
    evt.SetMessage("The barrel is filled with a strange black sludge. A note on the inside of the lid reads, \"Danger: Unpredictable Effects.\" Drink?")
    evt.AskQuestion(4, 1, 0, 2, "Drink (Yes/No)?", {"Yes", "Y"})
end, "Black barrel")

